{"content": "# -*- coding: utf-8 -*-
"""
固定燃烧源排放清单编制 — 通用工具调用型Agent (实验C R3, 目标类型 POWER 火电热力)
处理逻辑全部基于:
  1) 运行包内三张原始结构基表 (基102-2002 设备/燃料基表、基101-2001 企业主表、基101-2002 治理设施表)
  2) T/CSES 144-2024 《城市大气污染源排放清单编制技术指南》(inputs/T_CSES_144-2024.pdf)
  3) inputs/source_identity_index.json (source_id <-> 基102行 的稳定映射, 仅用于标识)
不读取任何运行包以外的代码、规则或结果。
"""
import json
import math
import os
import sys
import collections
import csv

import openpyxl

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from standard_tables import (
    POLLUTANTS, A1, C1, C2, C3, D1, FUEL_EF_MAP, FUEL_NO_EF, TECH_MAP,
    NOX_CAPACITY, POWER_INDUSTRY_SECTION, POWER_CODES,
    DESULFUR_TECHS, DENITR_TECHS, DUST_TECHS,
)

BASE = "/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/04_实验C_规模与资源表现/100%规模/02_火电热力/03_通用工具调用型Agent/R3"
INP = os.path.join(BASE, "inputs")
OUT = os.path.join(BASE, "outputs")
os.makedirs(OUT, exist_ok=True)

# ----------------------------------------------------------------------------
# 1. 读取基102-2002 (设备/燃料基表, 原始行粒度)
# ----------------------------------------------------------------------------
def load_b102():
    wb = openpyxl.load_workbook(os.path.join(INP, "基102-2002_原始结构脱敏输入.xlsx"), read_only=True)
    ws = wb["Sheet1"]
    rows = list(ws.iter_rows(values_only=True))
    wb.close()
    header = rows[0]
    data = rows[1:]
    # 位置索引 (表头存在同名重复列: 低氮燃烧 电站/工业各一组; 发电/供热消耗量 燃料一/二各一组)
    pos = {}
    for i, h in enumerate(header):
        pos.setdefault(h, []).append(i)
    H = {}
    for h, idxs in pos.items():
        if len(idxs) == 1:
            H[h] = idxs[0]
    # 重复列按顺序命名
    H["电站_低氮代码"] = pos["是否采用低氮燃烧技术代码"][0]
    H["电站_低氮"] = pos["是否采用低氮燃烧技术"][0]
    H["工业_低氮代码"] = pos["是否采用低氮燃烧技术代码"][1]
    H["工业_低氮"] = pos["是否采用低氮燃烧技术"][1]
    H["燃料一_发电消耗量"] = pos["其中：发电消耗量"][0]
    H["燃料一_发电消耗量单位"] = pos["其中：发电消耗量单位"][0]
    H["燃料一_供热消耗量"] = pos["其中：供热消耗量"][0]
    H["燃料一_供热消耗量单位"] = pos["其中：供热消耗量单位"][0]
    H["燃料二_发电消耗量"] = pos["其中：发电消耗量"][1]
    H["燃料二_发电消耗量单位"] = pos["其中：发电消耗量单位"][1]
    H["燃料二_供热消耗量"] = pos["其中：供热消耗量"][1]
    H["燃料二_供热消耗量单位"] = pos["其中：供热消耗量单位"][1]
    return header, data, H

HEADER, B102, H = load_b102()

def get(r, name):
    return r[H[name]]

def has(r, name):
    v = get(r, name)
    return v is not None and str(v).strip() != ""

def fnum(r, name):
    v = get(r, name)
    if v is None or str(v).strip() == "":
        return None
    try:
        return float(str(v).strip().replace(",", ""))
    except Exception:
        return None

def is_power_device(r):
    return has(r, "电站锅炉/燃气轮机编号")

def low_nitrogen_flag(r):
    key = "电站_低氮" if is_power_device(r) else "工业_低氮"
    v = get(r, key)
    if v is None:
        return False
    s = str(v).strip()
    return s in ("是", "1", "Y", "y", "true")

# ----------------------------------------------------------------------------
# 2. source_identity_index.json — source_id <-> 基102行
# ----------------------------------------------------------------------------
idx = json.load(open(os.path.join(INP, "source_identity_index.json"), encoding="utf-8"))
assert idx["identity_contract"] == "source_identity_v1"
assert len(idx["records"]) == len(B102)
REC_BY_ROW = {}
for rec in idx["records"]:
    row = int(rec["source_row"])
    assert 2 <= row <= len(B102) + 1
    REC_BY_ROW[row - 1] = rec  # 0-based data row index

# ----------------------------------------------------------------------------
# 3. 基101-2002 治理设施表 (按企业 统一社会信用代码 分组)
# ----------------------------------------------------------------------------
def load_facilities():
    wb = openpyxl.load_workbook(os.path.join(INP, "基101-2002_原始结构脱敏输入.xlsx"), read_only=True)
    ws = wb["Sheet1"]
    rows = list(ws.iter_rows(values_only=True))
    wb.close()
    header = rows[0]
    fh = {h: i for i, h in enumerate(header)}
    facs = collections.defaultdict(list)
    for r in rows[1:]:
        credit = r[fh["统一社会信用代码"]]
        if credit is None:
            continue
        eff = r[fh["去除效率（%）"]]
        try:
            eff = float(eff) if eff is not None and str(eff).strip() != "" else None
        except Exception:
            eff = None
        facs[str(credit)].append({
            "credit": str(credit),
            "industry": str(r[fh["行业类别代码"]]).strip() if r[fh["行业类别代码"]] is not None else "",
            "outlet_code": str(r[fh["对应的排放口代码"]]).strip() if r[fh["对应的排放口代码"]] is not None else "",
            "facility_name": str(r[fh["废气治理设施名称"]]).strip() if r[fh["废气治理设施名称"]] is not None else "",
            "process": str(r[fh["处理工艺名称"]]).strip() if r[fh["处理工艺名称"]] is not None else "",
            "efficiency": eff,
        })
    return facs

FACS = load_facilities()

# ----------------------------------------------------------------------------
# 4. 源分类 (依据 T/CSES 144-2024 3.5/3.6/5.2.1/5.2.2/7.1/8.1/8.3)
#    POWER: 行业 ∈ {4411火力发电, 4412热电联产, 4417生物质能发电, 4430热力生产和供应}
#    INDUSTRIAL_BOILER: 行业 ∈ 采矿业(06-12)/制造业(13-43)/燃气生产和供应业(45)
#    OUT_OF_SCOPE: 其余
# ----------------------------------------------------------------------------
def classify(ind_code):
    ind = str(ind_code).strip() if ind_code is not None else ""
    if ind in POWER_CODES:
        return "POWER"
    if len(ind) >= 2 and ind[:2].isdigit():
        two = int(ind[:2])
        if (6 <= two <= 12) or (13 <= two <= 43) or two == 45:
            return "INDUSTRIAL_BOILER"
    return "OUT_OF_SCOPE"

DECISION_REASON = {
    "POWER": {
        "4411": "POWER_INDUSTRY_4411_火力发电",
        "4412": "POWER_INDUSTRY_4412_热电联产",
        "4417": "POWER_INDUSTRY_4417_生物质能发电",
        "4430": "POWER_INDUSTRY_4430_热力生产和供应",
    },
    "INDUSTRIAL_BOILER": "INDUSTRIAL_SCOPE_BOILER_采矿制造燃气业",
    "OUT_OF_SCOPE": "OUT_OF_SCOPE_NOT_IN_STANDARD_SCOPE",
}

# ----------------------------------------------------------------------------
# 5. 治理设施 -> 技术映射 (处理工艺名称关键词 -> 表A.1技术)
# ----------------------------------------------------------------------------
def map_process_to_techs(facility_name, process):
    """返回 (tech list, target_pollutant)。target: SO2 / NOx / PM"""
    techs = []
    p = process or ""
    if "脱硫" in facility_name or "脱硫" in p:
        target = "SO2"
    elif "脱硝" in facility_name or "脱硝" in p:
        target = "NOx"
    elif "除尘" in facility_name or "除尘" in p or "尘" in facility_name:
        target = "PM"
    else:
        target = None
    # 脱硫技术
    if "石灰石/石膏" in p or "石灰/石膏" in p or "石膏法" in p:
        techs.append("石灰石/石膏法")
    if "双碱" in p:
        techs.append("双碱法")
    if "海水" in p:
        techs.append("海水法")
    if "氨法" in p or "氨-硫铵" in p:
        techs.append("氨法")
    if "炉内喷钙" in p or "炉内脱硫" in p:
        techs.append("炉内喷钙法")
    if "烟气循环流化床" in p:
        techs.append("烟气循环流化床法")
    if "旋转喷雾" in p or "半干法" in p or "消石灰半干法" in p:
        techs.append("旋转喷雾干燥法")
    if "钠碱" in p or "碱吸收" in p or "碱液" in p or "干法" in p or "洗涤塔" in p:
        techs.append("其他脱硫技术")
    if target == "SO2" and not techs:
        techs.append("其他脱硫技术")
    # 脱硝技术
    if "SNCR" in p.upper() or "选择性非催化还原" in p:
        techs.append("选择性非催化还原法")
    if "SCR" in p.upper() or "选择性催化还原" in p:
        techs.append("选择性催化还原法")
    if "低氮" in p:
        techs.append("低氮燃烧技术")
    if "氧化" in p and target == "NOx":
        techs.append("其他脱硝技术")
    if "烟气循环燃烧" in p:
        techs.append("低氮燃烧技术")  # 烟气再循环属低氮技术
    if target == "NOx" and not techs:
        techs.append("其他脱硝技术")
    # 除尘技术
    if "湿式电除尘" in p:
        techs.append("高效静电除尘法")  # 湿式电除尘, 表A.1无对应行, 以高效静电除尘法近似
    if "袋式" in p or "布袋" in p or "过滤除尘" in p or "覆膜" in p:
        techs.append("袋式除尘法")
    if "电袋" in p:
        techs.append("电袋复合除尘法")
    if "静电" in p:
        techs.append("高效静电除尘法" if "高效" in p else "普通静电除尘法")
    if "旋风" in p or "多管" in p:
        techs.append("多管旋风除尘法")
    if ("水膜" in p or "水浴" in p or "喷淋" in p or "文丘里" in p or
            "湿式" in p or "湿法" in p or "喷雾" in p or "洗涤" in p or "水帘" in p):
        techs.append("湿式除尘法")
    if "重力" in p:
        techs.append("重力沉降法")
    if target == "PM" and not techs:
        techs.append("其他除尘技术")
    # 去重
    seen = []
    for t in techs:
        if t not in seen:
            seen.append(t)
    return seen, target

# ----------------------------------------------------------------------------
# 6. 单源治理效率计算
# ----------------------------------------------------------------------------
def compute_controls(row, credit):
    """返回 dict: pollutant -> (efficiency, method_desc)。efficiency 为小数(0~1)。"""
    cat = "DZGL" if is_power_device(row) else "GYGL"
    facs = [f for f in FACS.get(credit, []) if f["outlet_code"] == cat]
    # 每个设施 -> (target, techs, actual)
    parsed = []
    for f in facs:
        techs, target = map_process_to_techs(f["facility_name"], f["process"])
        if not techs or target is None:
            continue
        parsed.append({"facility": f, "techs": techs, "target": target})

    # 低氮燃烧 (基102 填报 + 治理设施工艺)
    lowN = low_nitrogen_flag(row) or any(
        "低氮燃烧技术" in p["techs"] for p in parsed)

    # ---- 按技术分组取最大(去重), 再按污染物串联组合 ----
    tech_facilities = collections.defaultdict(list)
    for p in parsed:
        for t in p["techs"]:
            tech_facilities[t].append(p)

    def contrib(t, pollutant):
        """技术 t 对污染物 pollutant 的去除效率(小数)。"""
        a1 = A1[t].get(pollutant, 0) / 100.0
        effs = []
        for p in tech_facilities[t]:
            actual = p["facility"]["efficiency"]
            if pollutant == p["target"] and actual is not None:
                effs.append(actual / 100.0)
            else:
                effs.append(a1)
        return max(effs) if effs else a1

    def series(vals):
        r = 1.0
        for v in vals:
            r *= (1.0 - v)
        return 1.0 - r

    controls = {}
    # SO2
    so2_techs = [t for t in tech_facilities if A1[t].get("SO2", 0) > 0]
    controls["SO2"] = series([contrib(t, "SO2") for t in so2_techs]) if so2_techs else 0.0
    # NOx (特殊组合)
    scr = "选择性催化还原法" in tech_facilities
    sncr = "选择性非催化还原法" in tech_facilities
    if lowN:
        if scr:
            a = max([contrib("选择性催化还原法", "NOx")]) if False else None
            # 设施实际SCR效率(若有)与表A.1组合效率64%取大
            scr_eff = contrib("选择性催化还原法", "NOx")
            controls["NOx"] = max(scr_eff, 0.64)
        elif sncr:
            sncr_eff = contrib("选择性非催化还原法", "NOx")
            controls["NOx"] = max(sncr_eff, 0.52)
        else:
            controls["NOx"] = 0.22
    else:
        nox_techs = [t for t in tech_facilities if A1[t].get("NOx", 0) > 0]
        controls["NOx"] = series([contrib(t, "NOx") for t in nox_techs]) if nox_techs else 0.0
    # PM2.5 / PM2.5-10 / BC / OC
    pm_techs = [t for t in tech_facilities if A1[t].get("PM2.5", 0) > 0]
    controls["PM2.5"] = series([contrib(t, "PM2.5") for t in pm_techs]) if pm_techs else 0.0
    controls["PM2.5-10"] = series([contrib(t, "PM2.5-10") for t in pm_techs]) if pm_techs else 0.0
    controls["BC"] = series([contrib(t, "BC") for t in pm_techs]) if pm_techs else 0.0
    controls["OC"] = series([contrib(t, "OC") for t in pm_techs]) if pm_techs else 0.0
    controls["CO"] = 0.0
    controls["VOC"] = 0.0  # 标准8.2.1.2: 燃烧烟气源项不涉及VOCs末端治理, η=0
    controls["NH3"] = 0.0

    method_desc = []
    for t in tech_facilities:
        n = len(tech_facilities[t])
        method_desc.append("%s(%d套)" % (t, n))
    if lowN:
        method_desc.append("低氮燃烧技术")
    if not method_desc:
        method_desc = ["无治理设施"]
    return controls, " + ".join(method_desc)

# ----------------------------------------------------------------------------
# 7. 组件排放计算
# ----------------------------------------------------------------------------
def section_for_industry(ind):
    return POWER_INDUSTRY_SECTION[ind]

def coal_tech(row, section):
    """煤炭组件的燃烧技术; 返回None表示无法确定。"""
    tech_field = get(row, "电站锅炉燃烧方式") if is_power_device(row) else get(row, "工业锅炉燃烧方式")
    if tech_field is None:
        return None
    return TECH_MAP.get(str(tech_field).strip())

def resolve_ef(row, fuel_type, section):
    """返回 dict: pollutant -> (ef_value, unit_basis, source_desc) 或 None(该燃料无对应因子)"""
    if fuel_type in FUEL_NO_EF:
        return None
    if fuel_type not in FUEL_EF_MAP:
        return None
    d1_fuel, basis = FUEL_EF_MAP[fuel_type]
    fuel_rows = D1[section].get(d1_fuel)
    if fuel_rows is None:
        return None
    if d1_fuel == "煤炭":
        tech = coal_tech(row, section)
        if tech is None:
            return None
        d1_row = fuel_rows.get(tech)
        if d1_row is None:
            return None
    else:
        tech = next(iter(fuel_rows.keys()))
        d1_row = fuel_rows[tech]
    # 分污染物解析
    labels = ["CO", "NOx", "SO2", "VOC", "PM2.5", "PM10", "BC", "OC"]
    out = {}
    for lab, val in zip(labels, d1_row):
        if val == "MB":
            out[lab] = None  # 物料衡算, 需另行计算
        elif val == "CAP":
            cap_wan_kw = fnum(row, "对应机组装机容量（万千瓦）")
            if cap_wan_kw is None:
                out[lab] = None  # 装机容量缺失
            else:
                mw = cap_wan_kw * 10.0
                for lim, ef in NOX_CAPACITY:
                    if mw <= lim:
                        out[lab] = ef
                        break
        else:
            out[lab] = val
    return {"ef": out, "basis": basis, "fuel": d1_fuel, "tech": tech, "section": section}

def material_balance(row, fuel_type, section):
    """燃煤物料衡算: 返回 dict pollutant -> ef_g_per_kg (None表示缺参)"""
    tech = coal_tech(row, section)
    if tech is None:
        return {"SO2": None, "PM2.5": None, "PM10": None, "BC": None, "OC": None}
    c1 = C1.get(tech)
    c2 = C2.get(tech)
    c3 = C3.get(tech)
    if c1 is None or c2 is None or c3 is None:
        return {"SO2": None, "PM2.5": None, "PM10": None, "BC": None, "OC": None}
    s = fnum(row, "燃料一平均收到基含硫量") if fuel_type == "燃料一" else fnum(row, "燃料二平均收到基含硫量")
    a = fnum(row, "燃料一平均收到基灰分（%）") if fuel_type == "燃料一" else fnum(row, "燃料二平均收到基灰分（%）")
    res = {}
    # 公式(3): EF_SO2(g/kg) = 2 * S(质量分数) * (1-sr) * 1000 = 20*S(%)*(1-sr)
    res["SO2"] = (20.0 * s * (1 - c1["sr"])) if s is not None else None
    # 公式(4): EF_PM(g/kg) = Aar(质量分数) * (1-ar) * fPM * 1000 = 10*Aar(%)*(1-ar)*fPM
    if a is not None:
        res["PM2.5"] = 10.0 * a * (1 - c1["ar"]) * c2["PM2.5"]
        res["PM10"] = 10.0 * a * (1 - c1["ar"]) * c2["PM10"]
    else:
        res["PM2.5"] = None
        res["PM10"] = None
    # 公式(5)(6): EF_BC = EF_PM2.5 * fBC ; EF_OC = EF_PM2.5 * fOC
    if res["PM2.5"] is not None:
        res["BC"] = res["PM2.5"] * c3["BC"]
        res["OC"] = res["PM2.5"] * c3["OC"]
    else:
        res["BC"] = None
        res["OC"] = None
    return res

def build_component(row, fuel_type, section):
    """返回组件dict: 包含活动水平、参数、各污染物EF、单位基准、状态信息。"""
    if fuel_type == "燃料一":
        ftype = get(row, "燃料一类型")
        qty = fnum(row, "燃料一消耗量")
        unit = get(row, "燃料一消耗量单位")
        s = fnum(row, "燃料一平均收到基含硫量")
        a = fnum(row, "燃料一平均收到基灰分（%）")
        lhv = fnum(row, "燃料一低位发热量（千卡/千克或千卡/标准立方米）")
        id_ = "F1"
    elif fuel_type == "燃料二":
        ftype = get(row, "燃料二类型")
        qty = fnum(row, "燃料二消耗量")
        unit = get(row, "燃料二消耗量单位")
        s = fnum(row, "燃料二平均收到基含硫量")
        a = fnum(row, "燃料二平均收到基灰分（%）")
        lhv = fnum(row, "燃料二低位发热量（千卡/千克或千卡/标准立方米）")
        id_ = "F2"
    else:  # 其他燃料消耗总量
        ftype = None
        qty = fnum(row, "其他燃料消耗总量（吨标准煤）")
        unit = "吨标准煤"
        s = a = lhv = None
        id_ = "FO"

    comp = {
        "id": id_, "fuel_type": ftype, "qty": qty, "unit": unit,
        "sulfur": s, "ash": a, "lhv": lhv,
        "ef": {}, "basis": None, "d1_fuel": None, "d1_tech": None,
        "mb": {}, "status_detail": None, "reason": None,
    }
    if qty is None or qty <= 0:
        comp["status_detail"] = "not_involved" if qty == 0 else "information_insufficient"
        comp["reason"] = "ACTIVITY_ZERO" if qty == 0 else "ACTIVITY_MISSING"
        return comp
    if ftype is None:
        comp["status_detail"] = "information_insufficient"
        comp["reason"] = "FUEL_TYPE_MISSING"
        return comp
    if unit is None or str(unit).strip() == "":
        comp["status_detail"] = "source_data_invalid"
        comp["reason"] = "ACTIVITY_UNIT_MISSING"
        return comp
    unit = str(unit).strip()
    r = resolve_ef(row, ftype, section)
    if r is None:
        comp["status_detail"] = "information_insufficient"
        comp["reason"] = "EF_NOT_IN_STANDARD_FUEL" if ftype in FUEL_NO_EF else "EF_NOT_IN_STANDARD_TECHNOLOGY"
        return comp
    comp["basis"] = r["basis"]
    comp["d1_fuel"] = r["fuel"]
    comp["d1_tech"] = r["tech"]
    comp["ef"] = dict(r["ef"])
    if r["fuel"] == "煤炭":
        comp["mb"] = material_balance(row, fuel_type, section)
    # 汇总每个污染物最终EF (优先固定值, 煤炭的MB项取物料衡算)
    comp["ef_final"] = {}
    for p in ["SO2", "NOx", "CO", "VOC", "PM2.5", "PM10", "BC", "OC"]:
        v = comp["ef"].get(p)
        if v is None and p in comp["mb"]:
            v = comp["mb"][p]
        comp["ef_final"][p] = v
    return comp

def comp_emission(comp, pollutant):
    """按组件计算产生量/排放量(吨)。返回 (generation, emission, ok)"""
    ef = comp["ef_final"].get(pollutant)
    if ef is None or comp["qty"] is None or comp["unit"] is None:
        return None, None, False
    qty = comp["qty"]
    unit = comp["unit"]
    if unit == "吨":
        gen = qty * ef / 1000.0
    elif unit == "万立方米":
        gen = qty * ef / 100.0  # 万m3 * g/m3 /1e6 -> t  =>  *1e4/1e6 = /100
    elif unit == "吨标准煤":
        return None, None, False
    else:
        return None, None, False
    return gen, None, True

# ----------------------------------------------------------------------------
# 8. 主流程: 逐源生成记录
# ----------------------------------------------------------------------------
def industry_of(row):
    return str(get(row, "行业类别代码")).strip()

def build_all():
    decisions = []      # source_decisions
    dispositions = []   # generic_source_disposition
    items = []          # generic_inventory_items
    exceptions = collections.defaultdict(list)  # root_cause -> [source_ids...]

    for i, row in enumerate(B102):
        rec = REC_BY_ROW[i]
        source_id = rec["source_id"]
        ind = industry_of(row)
        decided = classify(ind)
        requested = "POWER"
        if decided == "POWER":
            reason_dec = DECISION_REASON["POWER"][ind]
            disposition = "in_scope_target"
        elif decided == "INDUSTRIAL_BOILER":
            reason_dec = DECISION_REASON["INDUSTRIAL_BOILER"]
            disposition = "classified_not_target"
        else:
            reason_dec = DECISION_REASON["OUT_OF_SCOPE"]
            disposition = "out_of_scope"
        decisions.append([source_id, requested, decided, disposition, reason_dec])
        dispositions.append([source_id, decided, disposition, reason_dec])

        if decided != "POWER":
            for p in POLLUTANTS:
                items.append({
                    "source_id": source_id, "target": decided, "pollutant": p,
                    "status": "not_involved", "method": "",
                    "activity_record_json": "[]", "parameter_record_json": "[]",
                    "control_record_json": "[]",
                    "generation_t": "", "emission_t": "",
                    "standard_reference": "", "reason_code": "TARGET_NOT_POWER",
                })
            continue

        # ---- POWER 源 ----
        credit = str(get(row, "统一社会信用代码"))
        section = section_for_industry(ind)
        comps = []
        if has(row, "燃料一类型") or has(row, "燃料一消耗量"):
            comps.append(build_component(row, "燃料一", section))
        if has(row, "燃料二类型") or has(row, "燃料二消耗量"):
            comps.append(build_component(row, "燃料二", section))
        if has(row, "其他燃料消耗总量（吨标准煤）"):
            comps.append(build_component(row, "其他燃料", section))

        controls, control_method = compute_controls(row, credit)

        # 组件级 JSON 记录
        act_elems = []
        par_elems = []
        for c in comps:
            act_elems.append({"component_id": c["id"], "value": c["qty"], "unit": c["unit"]})
            params = []
            if c["fuel_type"] is not None:
                params.append({"component_id": c["id"], "parameter_id": "FUEL_TYPE",
                               "mode": "source_data", "value": c["fuel_type"], "unit": "-"})
            if c["sulfur"] is not None:
                params.append({"component_id": c["id"], "parameter_id": "SULFUR_CONTENT",
                               "mode": "source_data", "value": c["sulfur"], "unit": "%"})
            if c["ash"] is not None:
                params.append({"component_id": c["id"], "parameter_id": "ASH_CONTENT",
                               "mode": "source_data", "value": c["ash"], "unit": "%"})
            if c["lhv"] is not None:
                params.append({"component_id": c["id"], "parameter_id": "LHV",
                               "mode": "source_data", "value": c["lhv"],
                               "unit": "千卡/千克或千卡/标准立方米"})
            if c["d1_fuel"] is not None:
                params.append({"component_id": c["id"], "parameter_id": "D1_FUEL",
                               "mode": "standard_D1", "value": c["d1_fuel"], "unit": "-"})
            if c["d1_tech"] is not None:
                params.append({"component_id": c["id"], "parameter_id": "D1_TECH",
                               "mode": "standard_D1", "value": c["d1_tech"], "unit": "-"})
            if c["basis"] is not None:
                params.append({"component_id": c["id"], "parameter_id": "EF_UNIT_BASIS",
                               "mode": "standard_D1",
                               "value": "g/kg" if c["basis"] == "solid" else "g/m3", "unit": "-"})
            for p, ef in c["ef_final"].items():
                if ef is None:
                    continue
                if p in ("SO2", "PM2.5", "PM10", "BC", "OC") and p in c["mb"]:
                    mode = "material_balance_formula3_6"
                else:
                    mode = "standard_D1"
                params.append({"component_id": c["id"], "parameter_id": "EF_%s" % p,
                               "mode": mode, "value": ef, "unit": "g/kg" if c["basis"] == "solid" else "g/m3"})
            par_elems.append(params)

        # 逐污染物行
        for p in POLLUTANTS:
            gen_total = 0.0
            emi_total = 0.0
            n_calc = 0
            n_comp = 0
            comp_reasons = set()
            status = "calculated"
            for c in comps:
                if c["status_detail"] == "not_involved":
                    continue
                n_comp += 1
                g, e, ok = comp_emission(c, p)
                if not ok:
                    comp_reasons.add(c["reason"] or "UNKNOWN")
                    continue
                eta = controls.get(p, 0.0)
                if p == "PM10":
                    eta = None  # PM10 用 fine/coarse
                n_calc += 1
                gen_total += g
                emi_total += g * (1.0 - controls.get(p, 0.0))
            if n_calc == 0:
                if n_comp == 0:
                    status = "not_involved"
                    rc = "NO_ACTIVE_COMPONENT"
                else:
                    status = "information_insufficient"
                    rc = ";".join(sorted(comp_reasons)) if comp_reasons else "EF_NOT_IN_STANDARD"
                gen_total = None
                emi_total = None
            else:
                if len(comp_reasons) > 0 and n_calc < n_comp:
                    rc = "CALCULATED_PARTIAL_COMPONENTS"
                else:
                    rc = "CALCULATED"
                status = "calculated"

            # 污染物特有的补充原因
            if status == "calculated" and p == "NH3":
                status = "information_insufficient"
                rc = "NH3_EF_NOT_PROVIDED"
                gen_total = None
                emi_total = None

            # control_record_json (按组件对齐)
            ctrl_elems = []
            for c in comps:
                if p == "PM10":
                    fine = controls.get("PM2.5", 0.0)
                    coarse = controls.get("PM2.5-10", 0.0)
                    ctrl_elems.append({
                        "component_id": c["id"], "method": control_method,
                        "efficiency": 0.0, "fine_efficiency": round(fine, 6),
                        "coarse_efficiency": round(coarse, 6),
                    })
                else:
                    ctrl_elems.append({
                        "component_id": c["id"], "method": control_method,
                        "efficiency": round(controls.get(p, 0.0), 6),
                        "fine_efficiency": 0.0, "coarse_efficiency": 0.0,
                    })

            act_json = json.dumps(act_elems, ensure_ascii=False)
            par_json = json.dumps(par_elems, ensure_ascii=False)
            ctrl_json = json.dumps(ctrl_elems, ensure_ascii=False)

            # standard_reference
            if status == "calculated":
                refs = set()
                for c in comps:
                    if c["d1_fuel"] is not None and c["d1_fuel"] == "煤炭":
                        refs.add("T/CSES144-2024 表D.1(%s-煤炭-%s)+公式(2)-(6)" % (section, c["d1_tech"]))
                    elif c["d1_fuel"] is not None:
                        refs.add("T/CSES144-2024 表D.1(%s-%s-%s)" % (section, c["d1_fuel"], c["d1_tech"]))
                refs.add("T/CSES144-2024 表A.1(治理效率)")
                std_ref = "；".join(sorted(refs))
            else:
                std_ref = "T/CSES144-2024 无对应产生系数或参数缺失"

            items.append({
                "source_id": source_id, "target": decided, "pollutant": p,
                "status": status, "method": method_for(status, p),
                "activity_record_json": act_json, "parameter_record_json": par_json,
                "control_record_json": ctrl_json,
                "generation_t": round(gen_total, 6) if gen_total is not None else "",
                "emission_t": round(emi_total, 6) if emi_total is not None else "",
                "standard_reference": std_ref, "reason_code": rc,
            })
            if status != "calculated":
                exceptions[rc].append(source_id)
            elif "PARTIAL" in rc:
                exceptions[rc].append(source_id)

    return decisions, dispositions, items, exceptions

def method_for(status, p):
    if status == "calculated":
        return "coefficient_method"
    return ""

# ----------------------------------------------------------------------------
# 9. 写出
# ----------------------------------------------------------------------------
def write_outputs(decisions, dispositions, items, exceptions):
    with open(os.path.join(OUT, "source_decisions.csv"), "w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f)
        w.writerow(["source_id", "requested_target", "decided_target", "disposition", "reason_code"])
        for r in decisions:
            w.writerow(r)
    with open(os.path.join(OUT, "generic_inventory_items.csv"), "w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f)
        w.writerow(["source_id", "target", "pollutant", "status", "method",
                    "activity_record_json", "parameter_record_json", "control_record_json",
                    "generation_t", "emission_t", "standard_reference", "reason_code"])
        for it in items:
            w.writerow([it["source_id"], it["target"], it["pollutant"], it["status"], it["method"],
                        it["activity_record_json"], it["parameter_record_json"], it["control_record_json"],
                        it["generation_t"], it["emission_t"], it["standard_reference"], it["reason_code"]])
    with open(os.path.join(OUT, "generic_source_disposition.csv"), "w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f)
        w.writerow(["source_id", "target", "disposition", "reason_code"])
        for r in dispositions:
            w.writerow(r)
    with open(os.path.join(OUT, "generic_exception_list.csv"), "w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f)
        w.writerow(["exception_id", "source_id", "pollutant", "root_cause", "action_required"])
        actions = {
            "EF_NOT_IN_STANDARD_FUEL": "该燃料(城市生活垃圾/生物燃料/工业废料/其他燃料)在T/CSES144-2024表D.1中无产生系数, 需补充实测或行业手册系数后方可核算",
            "EF_NOT_IN_STANDARD_TECHNOLOGY": "燃气轮机/余热利用锅炉等燃烧技术在T/CSES144-2024表D.1中无对应产生系数, 需补充相应技术因子",
            "NOX_CAPACITY_MISSING": "电力生产燃煤源缺对应机组装机容量, 表D.1注b无法取值, 需补充装机容量后核算NOx",
            "NH3_EF_NOT_PROVIDED": "T/CSES144-2024表D.1/E.7未提供固定燃烧源NH3产生系数, 需按氨源专项指南或实测数据补充",
            "FUEL_TYPE_MISSING": "其他燃料消耗总量未给出燃料类型且单位为吨标准煤, 无法选取产生系数, 需补充燃料构成",
            "ACTIVITY_MISSING": "该源无任何燃料消耗活动水平, 无法核算排放量",
            "ACTIVITY_ZERO": "该源填报燃料消耗量为0, 无排放贡献",
            "SULFUR_CONTENT_MISSING": "燃煤源缺平均收到基含硫量, 公式(3)无法计算SO2产生系数",
            "ASH_CONTENT_MISSING": "燃煤源缺平均收到基灰分, 公式(4)无法计算颗粒物产生系数",
            "COMBUSTION_TECH_MISSING": "燃煤源燃烧方式为'其他'或缺失, 表C.1~C.3/D.1无法确定对应技术, 需补充燃烧方式",
            "UNIT_NOT_SUPPORTED": "燃料消耗量单位无法换算至表D.1因子基准(g/kg或g/m3)",
            "CALCULATED_PARTIAL_COMPONENTS": "该源部分燃料组件已核算、部分组件缺因子/参数, 排放量为已核算组件之和, 需补充缺项后汇总",
            "ACTIVITY_UNIT_MISSING": "燃料消耗量单位缺失, 无法换算",
        }
        eid = 1
        for rc, srcs in sorted(exceptions.items()):
            poll = ""
            if rc == "NOX_CAPACITY_MISSING":
                poll = "NOx"
            elif rc == "NH3_EF_NOT_PROVIDED":
                poll = "NH3"
            else:
                poll = "SO2,NOx,CO,VOC,PM2.5,PM10,BC,OC"
            w.writerow(["EXC-%03d" % eid, srcs[0], poll, "%s (涉及%d个源)" % (rc, len(srcs)),
                        actions.get(rc, "需人工核实处理")])
            eid += 1
    return eid - 1

def main():
    decisions, dispositions, items, exceptions = build_all()
    n_exc = write_outputs(decisions, dispositions, items, exceptions)

    # ---- QC ----
    print("== 分类统计 ==")
    c = collections.Counter(d[2] for d in decisions)
    for k, v in c.items():
        print("  %s: %d" % (k, v))
    print("== 核算项状态统计 ==")
    cs = collections.Counter(it["status"] for it in items)
    for k, v in cs.items():
        print("  %s: %d" % (k, v))
    calc = [it for it in items if it["status"] == "calculated"]
    gen_sum = sum(float(it["generation_t"]) for it in calc)
    emi_sum = sum(float(it["emission_t"]) for it in calc)
    print("  calculated 项: %d, 产生量合计(吨): %.4f, 排放量合计(吨): %.4f" % (len(calc), gen_sum, emi_sum))
    print("== 异常根因组数: %d ==" % n_exc)
    for rc, srcs in sorted(exceptions.items()):
        print("  %s: %d 源" % (rc, len(srcs)))
    print("== 结果文件 ==")
    for fn in ["source_decisions.csv", "generic_inventory_items.csv",
               "generic_source_disposition.csv", "generic_exception_list.csv",
               "generic_run_summary.json"]:
        print("  %s" % os.path.join(OUT, fn))
    return items, decisions

if __name__ == "__main__":
    main()
